unsafe fn test_readonly_truncation(dir_fd: wasip1::Fd) {
    // Attempt to truncate the file by opening it with `OFLAGS_TRUNC`. The
    // directory was preopened with read-only file permissions, so the runtime
    // must reject this instead of silently truncating the file.
    let result = wasip1::path_open(
